contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore + depositAmount);
        uint collectBefore = address(c).balance;
        c.Collect(collectAmount); if (__ESBMC_reverted()) return;
        bool collectOk = address(c).balance != collectBefore;
        if (depositAmount >= minSum && depositAmount >= collectAmount) {
            assert(address(c).balance == collectBefore - collectAmount || !collectOk);
        } else {
            assert(address(c).balance == collectBefore);
        }
    }
    receive() external payable {}
}

